        "ledger/model.py": #"""
        """Transactions as the bank exports them."""

        from __future__ import annotations

        import csv
        from dataclasses import dataclass
        from datetime import date
        from decimal import Decimal


        @dataclass(frozen=True)
        class Transaction:
            day: date
            payee: str
            category: str
            amount: Decimal  # negative = money out

            @property
            def month(self) -> str:
                return self.day.strftime("%Y-%m")


        def load_csv(path: str) -> list[Transaction]:
            """Read `date,payee,category,amount` rows; blank categories become "Uncategorized"."""
            with open(path, newline="", encoding="utf-8") as handle:
                return [
                    Transaction(
                        day=date.fromisoformat(row["date"]),
                        payee=row["payee"].strip(),
                        category=row["category"].strip() or "Uncategorized",
                        amount=Decimal(row["amount"]),
                    )
                    for row in csv.DictReader(handle)
                ]
        """#,
        "ledger/report.py": #"""
        """Monthly totals and the text report."""

        from __future__ import annotations

        from collections import defaultdict
        from decimal import Decimal

        from ledger.model import Transaction


        def monthly_totals(transactions: list[Transaction]) -> dict[str, dict[str, Decimal]]:
            """Money in and out per month, oldest month first."""
            totals: dict[str, dict[str, Decimal]] = defaultdict(lambda: {"in": Decimal(0), "out": Decimal(0)})
            for t in transactions:
                side = "in" if t.amount > 0 else "out"
                totals[t.month][side] += abs(t.amount)
            return dict(sorted(totals.items()))


        def format_money(value: Decimal) -> str:
            return f"${value:,.2f}"


        def format_report(transactions: list[Transaction], month: str | None = None) -> str:
            lines = []
            for name, sums in monthly_totals(transactions).items():
                if month and name != month:
                    continue
                net = sums["in"] - sums["out"]
                lines.append(
                    f"{name}  in {format_money(sums['in']):>11}  out {format_money(sums['out']):>11}"
                    f"  net {format_money(net):>11}"
                )
            return "\n".join(lines) if lines else "No transactions."
