        """#,
        "ledger/report.py": #"""
        """Monthly totals and the text report."""

        from __future__ import annotations

        from collections import defaultdict
        from decimal import Decimal

        from ledger.model import Transaction


        def monthly_totals(transactions: list[Transaction]) -> dict[str, dict[str, Decimal]]:
            """Money in and out per month, oldest month first."""
            totals: dict[str, dict[str, Decimal]] = defaultdict(lambda: {"in": Decimal(0), "out": Decimal(0)})
            for t in transactions:
                side = "in" if t.amount > 0 else "out"
                totals[t.month][side] += abs(t.amount)
            return dict(sorted(totals.items()))


        def format_money(value: Decimal) -> str:
            return f"${value:,.2f}"


        def category_totals(transactions: list[Transaction]) -> dict[str, list[tuple[str, Decimal]]]:
            """Spending (money out) per category for each month, biggest first.

            Months are oldest first; ties are broken by category name.
            """
            spent: dict[str, dict[str, Decimal]] = defaultdict(lambda: defaultdict(Decimal))
            for t in transactions:
                if t.amount < 0:
                    spent[t.month][t.category] += -t.amount
            return {
                name: sorted(categories.items(), key=lambda item: (-item[1], item[0]))
                for name, categories in sorted(spent.items())
            }


        def format_report(
            transactions: list[Transaction], month: str | None = None, by_category: bool = False
        ) -> str:
            lines = []
            categories = category_totals(transactions) if by_category else {}
            for name, sums in monthly_totals(transactions).items():
                if month and name != month:
                    continue
                net = sums["in"] - sums["out"]
                lines.append(
                    f"{name}  in {format_money(sums['in']):>11}  out {format_money(sums['out']):>11}"
                    f"  net {format_money(net):>11}"
                )
                for category, amount in categories.get(name, []):
                    lines.append(f"    {category:<16}{format_money(amount):>11}")
            return "\n".join(lines) if lines else "No transactions."
