        "tests/test_report.py": #"""
        import contextlib
        import io
        import os
        import tempfile
        import unittest
        from datetime import date
        from decimal import Decimal

        from ledger.cli import main
        from ledger.model import Transaction
        from ledger.report import category_totals, format_report, monthly_totals


        def t(day: str, category: str, amount: str, payee: str = "Test") -> Transaction:
            return Transaction(date.fromisoformat(day), payee, category, Decimal(amount))


        class MonthlyTotalsTests(unittest.TestCase):
            def test_splits_money_in_and_out(self):
                totals = monthly_totals([t("2026-09-01", "Salary", "4200.00"), t("2026-09-03", "Groceries", "-86.40")])
                self.assertEqual(totals["2026-09"], {"in": Decimal("4200.00"), "out": Decimal("86.40")})

            def test_months_come_out_oldest_first(self):
                totals = monthly_totals([t("2026-10-02", "Rent", "-1850"), t("2026-08-30", "Rent", "-1850")])
                self.assertEqual(list(totals), ["2026-08", "2026-10"])

            def test_report_for_one_month(self):
                report = format_report([t("2026-09-01", "Salary", "10"), t("2026-10-01", "Salary", "20")], month="2026-10")
                self.assertIn("2026-10", report)
                self.assertNotIn("2026-09", report)

            def test_empty_report(self):
                self.assertEqual(format_report([]), "No transactions.")


        SAMPLE = [
            t("2026-09-01", "Salary", "4200.00"),
            t("2026-09-02", "Rent", "-1850.00"),
            t("2026-09-03", "Groceries", "-86.40"),
            t("2026-09-20", "Groceries", "-68.75"),
            t("2026-09-21", "Dining", "-10"),
            t("2026-09-22", "Utilities", "-10"),
            t("2026-10-01", "Dining", "-5"),
        ]


        class CategoryTotalsTests(unittest.TestCase):
            def test_biggest_first_and_sums_per_category(self):
                self.assertEqual(
                    category_totals(SAMPLE)["2026-09"],
                    [("Rent", Decimal("1850.00")), ("Groceries", Decimal("155.15")),
                     ("Dining", Decimal("10")), ("Utilities", Decimal("10"))],
                )

            def test_income_is_not_spending(self):
                self.assertNotIn("Salary", dict(category_totals(SAMPLE)["2026-09"]))

            def test_months_oldest_first(self):
                self.assertEqual(list(category_totals(list(reversed(SAMPLE)))), ["2026-09", "2026-10"])


        class ByCategoryReportTests(unittest.TestCase):
            def test_default_output_has_no_category_lines(self):
                report = format_report(SAMPLE)
                self.assertEqual(len(report.splitlines()), 2)
                self.assertNotIn("Rent", report)
                self.assertEqual(report, format_report(SAMPLE, by_category=False))

            def test_categories_listed_under_their_month(self):
                lines = format_report(SAMPLE, by_category=True).splitlines()
                self.assertEqual(len(lines), 2 + 4 + 1)
                self.assertTrue(lines[0].startswith("2026-09"))
                self.assertEqual([l.split()[0] for l in lines[1:5]], ["Rent", "Groceries", "Dining", "Utilities"])
                self.assertTrue(lines[5].startswith("2026-10"))
                self.assertIn("$1,850.00", lines[1])

            def test_month_lines_unchanged_by_flag(self):
                plain = format_report(SAMPLE).splitlines()
                with_cats = [l for l in format_report(SAMPLE, by_category=True).splitlines() if not l.startswith(" ")]
                self.assertEqual(plain, with_cats)

            def test_month_filter_applies(self):
                report = format_report(SAMPLE, month="2026-10", by_category=True)
                self.assertNotIn("Rent", report)
                self.assertIn("Dining", report)

            def test_month_with_only_income_has_no_category_lines(self):
                report = format_report([t("2026-09-01", "Salary", "10")], by_category=True)
                self.assertEqual(len(report.splitlines()), 1)


        class CliTests(unittest.TestCase):
            CSV = "date,payee,category,amount\n2026-09-02,Landlord,Rent,-100\n2026-09-03,Shop,,-5\n"

            def run_cli(self, *extra):
                with tempfile.NamedTemporaryFile("w", suffix=".csv", delete=False) as handle:
                    handle.write(self.CSV)
                self.addCleanup(os.unlink, handle.name)
                out = io.StringIO()
                with contextlib.redirect_stdout(out):
                    self.assertEqual(main(["report", handle.name, *extra]), 0)
                return out.getvalue()

            def test_flag_adds_breakdown(self):
                out = self.run_cli("--by-category")
                self.assertIn("Rent", out)
                self.assertIn("Uncategorized", out)

            def test_without_flag_unchanged(self):
                self.assertEqual(len(self.run_cli().splitlines()), 1)


        if __name__ == "__main__":
            unittest.main()
